#include <stdio.h>
void swap(int *p1, int *p2)
{
    int temp;
    temp=*p1;
    *p1=*p2;
    *p2=temp;
}
int main(void)
{
    int x=3, y=7;
    swap(&x, &y);
    printf("%d,%d\n", x, y);  /* 输出 7,3 */
    return 0;
}

